import{_ as l,a0 as p,w as r,s as o,ao as d,I as n,x as a,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在 LXD 2.3 及以上版本中管理網絡 | LCTT x X-CMD","titleTemplate":false,"description":"在 LXD 2.3 及以上版本中管理網絡 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 LXD 2.3 及以上版本中管理網絡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 LXD 2.3 及以上版本中管理網絡 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20161027 Network management with LXD","title":"在 LXD 2.3 及以上版本中管理網絡","tag":"201706","desc":""},"relativePath":"201706/20161027 Network management with LXD.md","filePath":"[post].md"}'),h={name:"201706/20161027 Network management with LXD.md"};function c(g,s,u,k,b,f){const e=p("Link");return r(),o("div",null,[s[25]||(s[25]=d(`<h1 id="在-lxd-2-3-及以上版本中管理網絡" tabindex="-1">在 LXD 2.3 及以上版本中管理網絡 <a class="header-anchor" href="#在-lxd-2-3-及以上版本中管理網絡" aria-label="Permalink to “在 LXD 2.3 及以上版本中管理網絡”">​</a></h1><p><img src="https://linuxcontainers.org/static/img/containers.png" alt="LXD logo"></p><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>當 LXD 2.0 隨着 Ubuntu 16.04 一起發佈時，LXD 聯網就簡單了。要麼你可以使用 <code>lxd init</code> 來配置，為你的容器自己提供一個 “lxdbr0” 網橋，要麼使用一個已存在的物理接口。</p><p>雖然這確實有效，但是有點混亂，因為大部分的橋接配置發生在 Ubuntu 打包的 LXD 之外。那些腳本只能支持一個橋接，並且沒有通過 API 暴露，這使得遠程配置有點痛苦。</p><p>直到 LXD 2.3，LXD 終於發展了自己的網絡管理 API ，並有相應的命令列工具。這篇文章試圖來簡述這些新的功能。</p><h3 id="基礎聯網" tabindex="-1">基礎聯網 <a class="header-anchor" href="#基礎聯網" aria-label="Permalink to “基礎聯網”">​</a></h3><p>在初始情況下，LXD 2.3 沒有定義任何網絡。<code>lxd init</code> 會為你設置一個，並且默認情況下將所有新的容器連接到它，但是讓我們親手嘗試看下究竟發生了些什麼。</p><p>要創建一個新的帶有隨機 IPv4 和 IP6 子網，並啓用 NAT 的網絡，只需要運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network create testbr0</span></span>
<span class="line"><span>Network testbr0 created</span></span></code></pre></div><p>你可以如下查看它的配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network show testbr0</span></span>
<span class="line"><span>name: testbr0</span></span>
<span class="line"><span>config:</span></span>
<span class="line"><span> ipv4.address: 10.150.19.1/24</span></span>
<span class="line"><span> ipv4.nat: &quot;true&quot;</span></span>
<span class="line"><span> ipv6.address: fd42:474b:622d:259d::1/64</span></span>
<span class="line"><span> ipv6.nat: &quot;true&quot;</span></span>
<span class="line"><span>managed: true</span></span>
<span class="line"><span>type: bridge</span></span>
<span class="line"><span>usedby: []</span></span></code></pre></div><p>如果你不想要那些自動配置的子網，你可以這麼做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network create testbr0 ipv6.address=none ipv4.address=10.0.3.1/24 ipv4.nat=true</span></span>
<span class="line"><span>Network testbr0 created</span></span></code></pre></div><p>那就會這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network show testbr0</span></span>
<span class="line"><span>name: testbr0</span></span>
<span class="line"><span>config:</span></span>
<span class="line"><span> ipv4.address: 10.0.3.1/24</span></span>
<span class="line"><span> ipv4.nat: &quot;true&quot;</span></span>
<span class="line"><span> ipv6.address: none</span></span>
<span class="line"><span>managed: true</span></span>
<span class="line"><span>type: bridge</span></span>
<span class="line"><span>usedby: []</span></span></code></pre></div><p>如果你的容器沒有使用它，那麼創建的網絡對你也沒什麼用。要將你新創建的網絡連接到所有容器，你可以這麼做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network attach-profile testbr0 default eth0</span></span></code></pre></div><p>要將一個網絡連接到一個已存在的容器中，你可以這麼做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network attach my-container default eth0</span></span></code></pre></div><p>現在，假設你已經在機器中安裝了 openvswitch，並且要將這個網橋轉換成 OVS 網橋，只需更改為正確的驅動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>stgraber@castiana:~$ lxc network set testbr0 bridge.driver openvswitch</span></span></code></pre></div><p>如果你想要一次性做一系列修改。<code>lxc network edit</code> 可以讓你在編輯器中交互編輯網絡配置。</p><h3 id="靜態租約及端口安全" tabindex="-1">靜態租約及端口安全 <a class="header-anchor" href="#靜態租約及端口安全" aria-label="Permalink to “靜態租約及端口安全”">​</a></h3><p>使用 LXD 管理 DHCP 服務器的一個好處是可以使得管理 DHCP 租約很簡單。你所需要的是一個容器特定的網卡設備以及正確的屬性設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@yak:~# lxc init ubuntu:16.04 c1</span></span>
<span class="line"><span>Creating c1</span></span>
<span class="line"><span>root@yak:~# lxc network attach testbr0 c1 eth0</span></span>
<span class="line"><span>root@yak:~# lxc config device set c1 eth0 ipv4.address 10.0.3.123</span></span>
<span class="line"><span>root@yak:~# lxc start c1</span></span>
<span class="line"><span>root@yak:~# lxc list c1</span></span>
<span class="line"><span>+------+---------+-------------------+------+------------+-----------+</span></span>
<span class="line"><span>| NAME |  STATE  |        IPV4       | IPV6 |    TYPE    | SNAPSHOTS |</span></span>
<span class="line"><span>+------+---------+-------------------+------+------------+-----------+</span></span>
<span class="line"><span>|  c1  | RUNNING | 10.0.3.123 (eth0) |      | PERSISTENT | 0         |</span></span>
<span class="line"><span>+------+---------+-------------------+------+------------+-----------+</span></span></code></pre></div><p>IPv6 也是相同的方法，但是換成 <code>ipv6.address</code> 屬性。</p><p>相似地，如果你想要阻止你的容器更改它的 MAC 地址或者為其他 MAC 地址轉發流量（比如嵌套），你可以用下面的命令啓用端口安全：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@yak:~# lxc config device set c1 eth0 security.mac_filtering true</span></span></code></pre></div><h3 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to “DNS”">​</a></h3><p>LXD 在網橋上運行 DNS 服務器。除了設置網橋的 DNS 域（ <code>dns.domain</code> 網絡屬性）之外，還支持 3 種不同的操作模式（<code>dns.mode</code>）：</p><ul><li><code>managed</code> ：每個容器都會有一條 DNS 記錄，匹配它的名字以及已知的 IP 地址。容器無法通過 DHCP 改變這條記錄。</li><li><code>dynamic</code> ：允許容器通過 DHCP 在 DNS 中自行註冊。因此，在 DHCP 協商期間容器發送的任何主機名最終都出現在 DNS 中。</li><li><code>none</code> ： 針對那些沒有任何本地 DNS 記錄的遞歸 DNS 服務器。</li></ul><p>默認的模式是 <code>managed</code>，並且典型的是最安全以及最方便的，因為它為容器提供了 DNS 記錄，但是不允許它們通過 DHCP 發送虛假主機名嗅探其他的記錄。</p><h3 id="使用隧道" tabindex="-1">使用隧道 <a class="header-anchor" href="#使用隧道" aria-label="Permalink to “使用隧道”">​</a></h3><p>除了這些，LXD 還支持使用 GRE 或者 VXLAN 隧道連接到其他主機。</p><p>LXD 網絡可以連接任何數量的隧道，從而輕鬆地創建跨多個主機的網絡。這對於開發、測試和演示非常有用，生產環境通常更喜歡使用 VLAN 進行分割。</p><p>所以説，你想在主機 “edfu” 上有一個運行 IPv4 和 IPv6 的基礎 “testbr0” 網絡，並希望在主機 “djanet” 上使用它來生成容器。最簡單的方法是使用組播 VXLAN 隧道。這種類型的隧道僅在兩個主機位於同一物理段上時才起作用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@edfu:~# lxc network create testbr0 tunnel.lan.protocol=vxlan</span></span>
<span class="line"><span>Network testbr0 created</span></span>
<span class="line"><span>root@edfu:~# lxc network attach-profile testbr0 default eth0</span></span></code></pre></div><p>它在主機 “edfu” 上定義了一個 “testbr0” 橋接，併為其他主機能加入它設置了一個組播 VXLAN。在這個設置中，“edfu” 為這個網絡扮演了一個路由器角色，提供 DHCP、DNS 等等，其他主機只是通過隧道轉發流量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@djanet:~# lxc network create testbr0 ipv4.address=none ipv6.address=none tunnel.lan.protocol=vxlan</span></span>
<span class="line"><span>Network testbr0 created</span></span>
<span class="line"><span>root@djanet:~# lxc network attach-profile testbr0 default eth0</span></span></code></pre></div><p>現在你可以在任何一台主機上啓動容器，並看到它們從同一個地址池中獲取 IP，通過隧道直接互相通訊。</p><p>如先前所述，這個使用了組播，它通常在跨越路由器時無法很好工作。在這些情況下，你可以用單播模式使用 VXLAN 或者 GRE 隧道。</p><p>要使用 GRE 加入另一台主機，首先配置服務主機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.nuturo.protocol gre</span></span>
<span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.nuturo.local 172.17.16.2</span></span>
<span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.nuturo.remote 172.17.16.9</span></span></code></pre></div><p>接着是“客户端”主機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@nuturo:~# lxc network create testbr0 ipv4.address=none ipv6.address=none tunnel.edfu.protocol=gre tunnel.edfu.local=172.17.16.9 tunnel.edfu.remote=172.17.16.2</span></span>
<span class="line"><span>Network testbr0 created</span></span>
<span class="line"><span>root@nuturo:~# lxc network attach-profile testbr0 default eth0</span></span></code></pre></div><p>如果你像使用 VXLAN，只要這麼做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.edfu.id 10</span></span>
<span class="line"><span>root@edfu:~# lxc network set testbr0 tunnel.edfu.protocol vxlan</span></span></code></pre></div><p>還有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@nuturo:~# lxc network set testbr0 tunnel.edfu.id 10</span></span>
<span class="line"><span>root@nuturo:~# lxc network set testbr0 tunnel.edfu.protocol vxlan</span></span></code></pre></div><p>這裏需要隧道 id 以防與已經配置的多播 VXLAN 隧道衝突。</p><p>這就是如何使用最近的 LXD 簡化跨主機聯網了！</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>LXD 使得從簡單的單主機網絡到數千個容器的非常複雜的跨主機網絡的定義變得更加容易。它也使為一些容器定義一個新網絡或者給容器添加第二個設備，並連接到隔離的私有網絡變得很簡單。</p>`,54)),n("p",null,[s[1]||(s[1]=a("雖然這篇文章介紹了支持的大部分功能，但仍有一些可以微調 LXD 網絡體驗的竅門。可以在這裏找到完整的列表：",-1)),t(e,{href:"https://github.com/lxc/lxd/blob/master/doc/configuration.md#network-configuration"},{default:i(()=>[...s[0]||(s[0]=[a("https://github.com/lxc/lxd/blob/master/doc/configuration.md",-1)])]),_:1}),s[2]||(s[2]=a(" 。",-1))]),s[26]||(s[26]=n("h3",{id:"額外信息",tabindex:"-1"},[a("額外信息 "),n("a",{class:"header-anchor",href:"#額外信息","aria-label":"Permalink to “額外信息”"},"​")],-1)),n("ul",null,[n("li",null,[s[4]||(s[4]=a("LXD 主站：",-1)),t(e,{href:"https://linuxcontainers.org/lxd"},{default:i(()=>[...s[3]||(s[3]=[a("https://linuxcontainers.org/lxd",-1)])]),_:1})]),n("li",null,[s[6]||(s[6]=a("Github 地址： ",-1)),t(e,{href:"https://github.com/lxc/lxd"},{default:i(()=>[...s[5]||(s[5]=[a("https://github.com/lxc/lxd",-1)])]),_:1})]),n("li",null,[s[8]||(s[8]=a("郵件列表支持：",-1)),t(e,{href:"https://lists.linuxcontainers.org/"},{default:i(()=>[...s[7]||(s[7]=[a("https://lists.linuxcontainers.org",-1)])]),_:1})]),s[11]||(s[11]=n("li",null,"IRC 頻道：#lxcontainers on irc.freenode.net",-1)),n("li",null,[s[10]||(s[10]=a("在線嘗試 LXD：",-1)),t(e,{href:"https://linuxcontainers.org/lxd/try-it"},{default:i(()=>[...s[9]||(s[9]=[a("https://linuxcontainers.org/lxd/try-it",-1)])]),_:1})])]),s[27]||(s[27]=n("hr",null,null,-1)),n("p",null,[s[13]||(s[13]=a("via: ",-1)),t(e,{href:"https://www.stgraber.org/2016/10/27/network-management-with-lxd-2-3/"},{default:i(()=>[...s[12]||(s[12]=[a("https://www.stgraber.org/2016/10/27/network-management-with-lxd-2-3/",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=a("作者：",-1)),t(e,{href:"https://www.stgraber.org/author/stgraber/"},{default:i(()=>[...s[14]||(s[14]=[a("Stéphane Graber",-1)])]),_:1}),s[18]||(s[18]=a(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[15]||(s[15]=[a("geekpi",-1)])]),_:1}),s[19]||(s[19]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[16]||(s[16]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[21]||(s[21]=[a("Linux中國",-1)])]),_:1}),s[24]||(s[24]=a(" 榮譽推出",-1))])])}const y=l(h,[["render",c]]);export{v as __pageData,y as default};
